select energy_manager.load_cards($cards$[
{"id":"p2-b08-041","paper":2,"topic":"Waste Heat Recovery","kind":"problem","front":"A furnace flue gas stream of 2,000 kg/h (Cp 0.25 kcal/kg °C) drops from 800 °C to 250 °C across a heat exchanger of 98% efficiency. (a) How much heat is recovered? (b) How many litres per hour of water can be heated by 50 °C from this heat?","back":"(a) 2,69,500 kcal/h. (b) 5,390 litres/h.","explain":"This is short question S-2 in the book, which gives no answer key. The working uses Q = m × Cp × ΔT × efficiency, and assumes water density of 1 kg/L.","flash":false,"source":"BEE Book 2 Ch 08 p264","steps":[{"prompt":"Find the temperature drop of the flue gas.","answer":"800 − 250 = 550 °C.","explain":"Only the temperature drop across the exchanger is recovered."},{"prompt":"Find the heat available from the gas stream.","answer":"2,000 × 0.25 × 550 = 2,75,000 kcal/h.","explain":"This is mass flow × Cp × ΔT."},{"prompt":"Apply the 98% exchanger efficiency.","answer":"2,75,000 × 0.98 = 2,69,500 kcal/h recovered.","explain":"The exchanger does not recover all the available heat."},{"prompt":"Find the water heated by 50 °C.","answer":"2,69,500 ÷ (1 × 50) = 5,390 kg/h, which is about 5,390 litres/h at water density 1 kg/L.","explain":"Water heat needed per kg is Cp × ΔT, with Cp of water taken as 1 kcal/kg °C."}],"order":2419},
{"id":"p2-b09-001","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What are the three ways heat flows from a warm medium to a cooler one?","back":"Radiation (warm surface to a cooler surface across an air space), conduction (through solid or fluid materials) and convection (by physical movement of air).","explain":"Heat transfer is the flow of thermal energy from a hotter object to a cooler one. Radiation needs no medium, conduction moves heat through material without bulk movement, and convection carries heat along with moving air or fluid.","flash":true,"source":"BEE Book 2 Ch 09 p269","order":2420},
{"id":"p2-b09-002","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What four criteria govern the rate of heat transfer between a hot and a cold fluid?","back":"(1) Temperature difference between the fluids; (2) area of the conductive barrier; (3) resistance to heat flow in each fluid; (4) material of the barrier, which must be compatible with the process fluids and must not corrode or contaminate them.","explain":"A larger temperature difference and a larger area both raise the heat flow. High resistance on either fluid side slows the overall rate, so the barrier material is chosen for compatibility as well as conductivity.","flash":false,"source":"BEE Book 2 Ch 09 p269","order":2421},
{"id":"p2-b09-003","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What is a heat exchanger?","back":"A device that transfers heat energy from one fluid to another, generally without mixing the two fluids.","explain":"Heat only flows from hotter to cooler, so the two fluids must be at different temperatures and in thermal contact. They stay separate, which is why the design uses walls or tubes between them.","flash":true,"source":"BEE Book 2 Ch 09 p269","order":2422},
{"id":"p2-b09-004","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"Name the five purposes a heat exchanger can serve.","back":"(1) Heat a cooler fluid with a hotter one; (2) cool a hot fluid with a cooler one; (3) boil a liquid with a hotter fluid; (4) condense a gas with a cooler fluid; (5) boil a liquid while condensing a hotter gas.","explain":"The purposes cover sensible heating or cooling and phase change. Recognising the purpose tells you whether the exchange is sensible, latent or both.","flash":false,"source":"BEE Book 2 Ch 09 p269","order":2423},
{"id":"p2-b09-005","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"Is the heat lost by the hot fluid exactly equal to the heat gained by the cold fluid in a real heat exchanger?","back":"No. In theory they are equal, but environmental heat losses make them differ slightly. Calculations assume they are equal to simplify the work, and insulation keeps the losses small.","explain":"The energy balance (heat lost by hot side = heat gained by cold side) is the basis of exchanger calculations. Insulating equipment and piping minimises the losses that the simplification ignores.","flash":false,"source":"BEE Book 2 Ch 09 p270","order":2424},
{"id":"p2-b09-006","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What does Q = m × Cₚ × ΔT give, and what are its units?","back":"Heat transferred Q in kW, where m is mass flow in kg/s, Cₚ is specific heat in kJ/kg·°C and ΔT is the temperature difference between the fluid's inlet and outlet in °C.","explain":"This is the sensible heat gained or lost by a fluid with no phase change. Apply it to each stream separately, then use the energy balance to link the hot and cold sides.","flash":true,"source":"BEE Book 2 Ch 09 p270","order":2425},
{"id":"p2-b09-007","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What is the basic heat exchanger design equation?","back":"Q = U × A × ΔT_LMTD, where Q is the heat transfer rate, U the overall heat transfer coefficient, A the heat transfer surface area and ΔT_LMTD the log mean temperature difference.","explain":"The equation links the heat duty to the driving force and the surface. For a known duty, a higher U or a higher ΔT_LMTD means less area is needed. It can be rearranged to size the area.","flash":false,"source":"BEE Book 2 Ch 09 p271","order":2426},
{"id":"p2-b09-008","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What LMTD value is used when the temperature difference between the two fluids is the same at both ends of the exchanger?","back":"The log mean formula gives zero in this case, so the LMTD is taken as the temperature difference at each end (the terminal temperature difference). In the book's example that is 30 °C.","explain":"When the temperature difference is constant along the length, the log formula breaks down. Using the terminal difference keeps the design equation usable.","flash":false,"source":"BEE Book 2 Ch 09 p272","order":2427},
{"id":"p2-b09-009","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What does the overall heat transfer coefficient U depend on?","back":"The conductivity of the wall separating the fluids, the convection coefficients on the hot and cold sides, the wall thickness and the fouling coefficients. In practice U is often found by measuring the other parameters and calculating it.","explain":"U combines all the resistances between the two fluids. Fouling deposits add resistance, so they lower U.","flash":false,"source":"BEE Book 2 Ch 09 p272","order":2428},
{"id":"p2-b09-010","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"Between what limits does the temperature correction factor F usually lie, and when can F be taken as 1?","back":"F usually lies between 0.85 and 0.98. F can be taken as 1 only when the flow is purely counter-current.","explain":"F corrects the LMTD for exchangers that are not truly counter-current, which is common in cross-flow and multi-pass designs. Charts or a numerical method are used to find F for a given configuration.","flash":false,"source":"BEE Book 2 Ch 09 p273","order":2429},
{"id":"p2-b09-011","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What are the three broad flow-pattern classes of heat exchangers?","back":"Counter flow, parallel flow and cross flow.","explain":"The classes describe how the hot and cold fluids move relative to each other. Flow pattern, along with available space and economics, sets the type and configuration of an exchanger.","flash":true,"source":"BEE Book 2 Ch 09 p273","order":2430},
{"id":"p2-b09-012","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"When is a counter-flow design most valuable?","back":"When there is a temperature cross, meaning the desired outlet temperature of one fluid lies between the inlet and outlet temperatures of the other fluid.","explain":"In counter flow the hottest cold-side outlet meets the hottest hot-side inlet, so the cold fluid can be heated above the hot fluid's outlet temperature. A true counter flow is hard to build for many applications, but plate, double-pipe and spiral exchangers come close.","flash":false,"source":"BEE Book 2 Ch 09 p274","order":2431},
{"id":"p2-b09-013","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"Where are cross-flow designs commonly used, and why?","back":"In most shell-and-tube and air-cooled exchangers, because a counter-flow layout is sometimes impractical due to high flow volumes or space restrictions.","explain":"In cross flow the two fluids move at right angles. Most applications use multiple passes, which combine cross flow and counter flow and can produce a partial temperature cross.","flash":false,"source":"BEE Book 2 Ch 09 p275","order":2432},
{"id":"p2-b09-014","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What is a double-pipe heat exchanger and where is it used?","back":"Two concentric tubes, with one fluid in the inner tube and the other in the annular space between the tubes. It is used for cooling process fluids where only small heat transfer areas are needed.","explain":"It is one of the simplest configurations. It can run in parallel or counter flow, and several units can be combined in series or parallel to form a system.","flash":false,"source":"BEE Book 2 Ch 09 p275","order":2433},
{"id":"p2-b09-015","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"In a shell-and-tube exchanger, why is the process fluid usually placed inside the tubes?","back":"For ease of cleaning, and to use the higher pressure capability inside the tubes.","explain":"Tubes handle higher pressure better than the shell, and the tube side is easier to clean. Baffles on the shell side direct the flow across the tubes and support them.","flash":false,"source":"BEE Book 2 Ch 09 p276","order":2434},
{"id":"p2-b09-016","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What are the main advantages and the main limitation of plate heat exchangers?","back":"Advantages: high heat transfer coefficients and area, low pressure drop and very high effectiveness. Limitation: relatively low pressure capability.","explain":"Corrugated plates increase turbulence and heat transfer. Plate exchangers suit duties with modest pressure where high effectiveness is needed.","flash":false,"source":"BEE Book 2 Ch 09 p276","order":2435},
{"id":"p2-b09-017","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"How does the overall heat transfer coefficient of a plate exchanger compare with a traditional shell-and-tube exchanger?","back":"Plate exchangers can reach about 8,000 W/m²·°C under favourable conditions. Traditional shell-and-tube exchangers are usually below 2,500 W/m²·°C.","explain":"The much higher U of plate units means a smaller area for the same duty. This is one reason plate units suit close temperature approaches.","flash":true,"source":"BEE Book 2 Ch 09 p277","order":2436},
{"id":"p2-b09-018","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"Why is counter flow usually preferred, and when is parallel flow chosen instead?","back":"Counter flow gives a larger effective LMTD, so a smaller area and greater potential energy recovery. Parallel flow is chosen for a high initial heating rate, for moderate tube wall temperatures (useful where fouling is aggravated by high temperature) or for rapid heating of viscous fluids.","explain":"A larger LMTD means less area for the same heat transfer. Parallel flow gives cooler tube walls and a fast start, which can cut pumping needs for viscous fluids.","flash":false,"source":"BEE Book 2 Ch 09 p277","order":2437},
{"id":"p2-b09-019","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"How do surface condensers differ from barometric condensers?","back":"Surface condensers circulate cooling water through tubes, so steam condenses on a cool surface and the condensate is collected. Barometric condensers rely on direct contact between the cooling water and the steam.","explain":"Surface condensers keep the condensate separate from the cooling water, so it can be returned and reused. Barometric units are simpler but mix the cooling water with the steam.","flash":false,"source":"BEE Book 2 Ch 09 p280","order":2438},
{"id":"p2-b09-020","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What is the role of a condenser in a steam turbine or ejector system?","back":"In turbine applications it runs under vacuum and removes a significant amount of latent heat from the exhaust steam, which is recovered as condensate. In ejector applications it condenses the motive steam and condensable vapours, reducing the motive steam needed.","explain":"Recovering the condensate returns hot water to the system instead of losing it. In ejector systems, condensing the motive steam cuts the steam the ejector consumes.","flash":false,"source":"BEE Book 2 Ch 09 p280","order":2439},
{"id":"p2-b09-021","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"Why is steam injected into the bottom of a distillation tower?","back":"To reduce the partial pressures of the hydrocarbons, which facilitates their separation and reduces coke formation on tray surfaces.","explain":"Distillation separates crude oil or feedstock into components by their boiling points. The lower partial pressure helps the components separate, and it also reduces coking on the trays.","flash":false,"source":"BEE Book 2 Ch 09 p280","order":2440},
{"id":"p2-b09-022","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What does an evaporator do and how is it usually built?","back":"It reduces the water content of a liquid, usually by heating it with steam, to concentrate the product. Most are shell-and-tube exchangers with steam on the shell side and the product being concentrated in the tubes.","explain":"Evaporators are used widely in food processing, chemicals, steel, forest products and textiles. They can be single-effect or multiple-effect.","flash":false,"source":"BEE Book 2 Ch 09 p281","order":2441},
{"id":"p2-b09-023","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"Roughly what fraction of the steam of a single-effect evaporator is needed after adding a first effect, and then a second effect?","back":"Adding one effect cuts steam use to nearly 50% of the original. Adding another effect brings it to nearly 33%.","explain":"Each effect reuses the latent heat of the vapour from the previous effect. The savings drop off with each added effect, which is why the number of effects is limited.","flash":true,"source":"BEE Book 2 Ch 09 p282","order":2442},
{"id":"p2-b09-024","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"Why does reduced heat transfer in an exchanger matter for a process?","back":"It almost always affects cycle time and product cost. Exchanger performance should be monitored and maintained at regular intervals set by cost-benefit criteria.","explain":"Efficient heating and cooling depend on good heat transfer from the surfaces. A good operation and maintenance policy starts at installation and continues in later years.","flash":false,"source":"BEE Book 2 Ch 09 p282","order":2443},
{"id":"p2-b09-025","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What happens to utility requirements and to exchanger area when the minimum approach temperature (ΔTmin) in pinch analysis is increased?","back":"Utility requirements (steam and cooling) increase, and area requirements decrease.","explain":"A larger ΔTmin means less heat is recovered, so more hot and cold utility is needed. A larger approach temperature also means the exchangers can be smaller.","flash":false,"source":"BEE Book 2 Ch 09 p283","order":2444},
{"id":"p2-b09-026","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"In pinch analysis, what is the defining parameter that decides whether a hot and cold stream match is suitable?","back":"Quality, which for heat means temperature.","explain":"Pinch treats a process as supplies and demands of commodities such as energy or water. Inefficient transfer between mismatched streams wastes the imported utility.","flash":false,"source":"BEE Book 2 Ch 09 p283","order":2445},
{"id":"p2-b09-027","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What do the hot and cold composite curves show in pinch analysis?","back":"The hot composite curve shows the process's heat availability and the cold composite curve shows its heat demands. The degree to which they overlap is the potential for heat recovery.","explain":"Building the curves needs a complete and consistent heat and mass balance. Sliding one curve horizontally changes only the relative position, not the stream data.","flash":false,"source":"BEE Book 2 Ch 09 p284","order":2446},
{"id":"p2-b09-028","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"In the chapter's composite-curve example with ΔTmin = 10 °C, what are the minimum hot and cold utility loads?","back":"Minimum hot utility Q_Hmin = 900 kW. Minimum cold utility Q_Cmin = 750 kW.","explain":"The heating and cooling that remain after maximum internal recovery between the composite curves give these targets. They set the energy target before any heat exchanger is designed.","flash":false,"source":"BEE Book 2 Ch 09 p286","order":2447},
{"id":"p2-b09-029","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"What is the main advantage of pinch technology over conventional design methods?","back":"It sets energy and capital cost targets for a process or a whole site before design, so the scope for energy savings and the investment needed can be judged before projects are identified.","explain":"Targets come from stream data alone. Pinch also guides debottlenecking, choice of combined heat and power, and recovery of low-grade waste heat.","flash":false,"source":"BEE Book 2 Ch 09 p287","order":2448},
{"id":"p2-b09-030","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"For a given heat duty and temperature difference, does a higher heat transfer coefficient need a larger or a smaller area?","back":"A smaller area. From A = Q / (U × ΔT_LMTD), a higher U reduces A.","explain":"A higher U means heat passes through the wall more readily, so less surface is needed. This is why high-U plate exchangers can be compact.","flash":true,"source":"BEE Book 2 Ch 09 p289","order":2449},
{"id":"p2-b09-031","paper":2,"topic":"Heat Exchangers","kind":"fact","front":"Does an exchanger's effectiveness depend on the LMTD?","back":"No. Effectiveness is the ratio of the actual heat transferred to the heat that an exchanger of infinite size could transfer. It is built from the flow heat capacities and inlet temperatures, not the LMTD.","explain":"Effectiveness is the best way to compare different types of exchanger. The LMTD is an average temperature difference used in the design equation and is not part of the effectiveness definition.","flash":false,"source":"BEE Book 2 Ch 09 p289","order":2450},
{"id":"p2-b09-032","paper":2,"topic":"Heat Exchangers","kind":"problem","front":"How much heat does 1,000 kg of water gain when it is heated from 30 °C to 70 °C (Cₚ = 1 kcal/kg·°C)?","back":"40,000 kcal (Q = 1,000 × 1 × 40).","explain":"This is a direct use of the sensible heat formula, with the specific heat of water given in kcal, so the answer is in kcal.","flash":false,"source":"BEE Book 2 Ch 09 p289","steps":[{"prompt":"Which formula gives the heat gained by a fluid with no phase change?","answer":"Q = m × Cₚ × ΔT","explain":"This is the sensible heat formula used throughout the chapter."},{"prompt":"Find the temperature rise.","answer":"ΔT = 70 − 30 = 40 °C","explain":"The rise is the outlet temperature minus the inlet temperature."},{"prompt":"Calculate the heat gained.","answer":"Q = 1,000 × 1 × 40 = 40,000 kcal","explain":"Specific heat is 1 kcal/kg·°C, so the result is in kcal, not kJ."}],"order":2451},
{"id":"p2-b09-033","paper":2,"topic":"Heat Exchangers","kind":"problem","front":"A process stream is cooled from 94 °C to 65 °C while cooling water is heated from 30 °C to 46 °C. What is the log mean temperature difference (LMTD)?","back":"About 41.2 °C.","explain":"The LMTD is an average driving force between the two end temperature differences. It lies between the two end differences and is lower than their arithmetic mean.","flash":false,"source":"BEE Book 2 Ch 09 p272","steps":[{"prompt":"Find the temperature difference at the first end.","answer":"ΔT₁ = 94 − 46 = 48 °C","explain":"Pair the hot inlet with the cold outlet, as in the book's example."},{"prompt":"Find the temperature difference at the other end.","answer":"ΔT₂ = 65 − 30 = 35 °C","explain":"Pair the hot outlet with the cold inlet."},{"prompt":"Apply the LMTD formula.","answer":"LMTD = (ΔT₁ − ΔT₂) / ln(ΔT₁/ΔT₂) = (48 − 35) / ln(48/35) = 13 / 0.316 = 41.2 °C","explain":"The log mean of the two end differences is the single average used in Q = U × A × ΔT_LMTD."}],"order":2452},
{"id":"p2-b09-034","paper":2,"topic":"Heat Exchangers","kind":"problem","front":"In the chapter's pipe-cooler example, milk (0.4 kg/s, Cₚ 3,890 J/kg·°C) is cooled from 49 °C to 18 °C in a 2.5 cm bore pipe. The bath is at 10 °C and U = 900 J/m²·s·°C. What pipe length is needed?","back":"About 34.8 m, which gives 2.73 m² of surface.","explain":"Heat removed is found from the energy balance, then the design equation gives the area, and the pipe geometry gives the length.","flash":false,"source":"BEE Book 2 Ch 09 p278","steps":[{"prompt":"Find the heat removed from the milk.","answer":"q = 3,890 × 0.4 × (49 − 18) = 48,240 J/s","explain":"Mass flow times specific heat times the temperature drop."},{"prompt":"Find the log mean temperature difference with the bath at 10 °C.","answer":"ΔT_lm = [(49 − 10) − (18 − 10)] / ln[(49 − 10)/(18 − 10)] = 31 / ln(4.875) = 19.6 °C","explain":"The bath is the constant second fluid, so both ends are measured from 10 °C."},{"prompt":"Find the required area.","answer":"A = q / (U × ΔT_lm) = 48,240 / (900 × 19.6) = 2.73 m²","explain":"This is the design equation Q = U × A × ΔT rearranged for A."},{"prompt":"Find the pipe length.","answer":"A = π × D × L, so L = 2.73 / (π × 0.025) = 34.8 m","explain":"The heat transfer area of a pipe is its circumference times its length."}],"order":2453},
{"id":"p2-b09-035","paper":2,"topic":"Heat Exchangers","kind":"problem","front":"In a counter-flow exchanger, brine (1.8 kg/s, Cₚ 3.38 kJ/kg·°C) enters at −8 °C and leaves at 10 °C, cooling water (1.05 kg/s, Cₚ 4.18 kJ/kg·°C) that enters at 32 °C. The area is 55 m². Find the water outlet temperature and the overall U.","back":"Water leaves at about 7 °C. U ≈ 0.11 kW/m²·°C (about 110 W/m²·°C).","explain":"Heat balance gives the unknown outlet temperature. The LMTD then gives U from the design equation.","flash":false,"source":"BEE Book 2 Ch 09 p279","steps":[{"prompt":"Find the heat gained by the brine.","answer":"Q = 1.8 × 3.38 × [10 − (−8)] = 109.5 kW","explain":"Heat lost by the brine equals heat gained by the water."},{"prompt":"Find the water outlet temperature.","answer":"109.5 = 1.05 × 4.18 × (32 − T), so 32 − T = 25.0 and T ≈ 7 °C","explain":"Solve the water heat balance for the unknown outlet temperature."},{"prompt":"Find the two end temperature differences.","answer":"ΔT₁ = 32 − 10 = 22 °C; ΔT₂ = 7 − (−8) = 15 °C","explain":"In counter flow the water inlet is paired with the brine outlet, and the water outlet with the brine inlet."},{"prompt":"Find the LMTD.","answer":"ΔT_lm = (22 − 15) / ln(22/15) = 7 / 0.383 = 18.3 °C","explain":"Log mean of the two end differences."},{"prompt":"Find U.","answer":"U = Q / (A × ΔT_lm) = 109.5 / (55 × 18.3) = 0.109 kW/m²·°C ≈ 0.11 kW/m²·°C, or about 110 W/m²·°C","explain":"kW divided by m² and °C gives kW/m²·°C, which is the same as kJ/m²·s·°C."}],"order":2454},
{"id":"p2-b09-036","paper":2,"topic":"Heat Exchangers","kind":"problem","front":"A counter-flow double-pipe exchanger heats 10.5 m³/h of water from 30 °C to 90 °C (Cₚ 4.18 kJ/kg·°C). The process liquid enters at 180 °C and leaves at 130 °C. With U = 814 W/m²·°C, find (a) the counter-flow area and (b) the % increase in area if the flows were parallel.","back":"(a) About 9.5 m². (b) About 14% more area (10.8 m²) for parallel flow.","explain":"The same duty needs more area in parallel flow because its LMTD is smaller. This is the book's solved example.","flash":false,"source":"BEE Book 2 Ch 09 p288","steps":[{"prompt":"Find the water mass flow and the heat duty.","answer":"10.5 m³/h = 10,500 kg/h; Q = 10,500 × 4.18 × 60 = 2,633,400 kJ/h = 731.5 kW","explain":"Divide kJ/h by 3,600 to get kW."},{"prompt":"Find the counter-flow LMTD.","answer":"ΔT₁ = 180 − 90 = 90 °C; ΔT₂ = 130 − 30 = 100 °C; LMTD = (100 − 90) / ln(100/90) ≈ 95 °C","explain":"Counter flow pairs the hot inlet with the cold outlet."},{"prompt":"Find the counter-flow area.","answer":"A = 731.5 × 1000 / (814 × 95) = 9.5 m²","explain":"Design equation with Q in W."},{"prompt":"Find the parallel-flow LMTD.","answer":"ΔT₁ = 180 − 30 = 150 °C; ΔT₂ = 130 − 90 = 40 °C; LMTD = (150 − 40) / ln(150/40) ≈ 83 °C","explain":"Parallel flow pairs the two inlets and the two outlets."},{"prompt":"Find the parallel-flow area and the % increase.","answer":"A = 731.5 × 1000 / (814 × 83) = 10.8 m²; increase = (10.8 − 9.5) / 9.5 × 100 ≈ 14%","explain":"The smaller LMTD of parallel flow needs more area for the same duty."}],"order":2455},
{"id":"p2-b09-037","paper":2,"topic":"Heat Exchangers","kind":"problem","front":"Stream 1 is cooled from 200 °C to 100 °C, releasing 2,000 kW. What is its heat capacity flow rate CP?","back":"CP = 20 kW/°C.","explain":"CP is the slope of the stream's enthalpy against temperature. It equals mass flow times specific heat.","flash":false,"source":"BEE Book 2 Ch 09 p284","steps":[{"prompt":"Identify the heat duty and the temperature change.","answer":"Q = 2,000 kW; ΔT = 200 − 100 = 100 °C","explain":"Use the stream's own data."},{"prompt":"Apply CP = Q / ΔT.","answer":"CP = 2,000 / 100 = 20 kW/°C","explain":"Heat duty divided by temperature change gives the slope of the stream line."},{"prompt":"Check what CP represents.","answer":"CP = (mass flow) × (specific heat), so 20 kW/°C is the product of the flow rate and Cₚ.","explain":"This is why CP is used to build composite curves from several streams."}],"order":2456},
{"id":"p2-b09-038","paper":2,"topic":"Heat Exchangers","kind":"problem","front":"In the 150 °C to 100 °C interval of the hot composite curve, Stream 1 (CP 20 kW/°C) and Stream 2 (CP 40 kW/°C) are both present. What is the hot composite CP in this interval?","back":"60 kW/°C (20 + 40).","explain":"Hot composite CP in each temperature interval is the sum of the CPs of the streams present in it.","flash":false,"source":"BEE Book 2 Ch 09 p285","steps":[{"prompt":"Identify which hot streams cover the interval 150 °C to 100 °C.","answer":"Stream 1 (200 to 100 °C) and Stream 2 (150 to 60 °C) both cover it.","explain":"A stream contributes only within its own temperature range."},{"prompt":"Find each stream's CP.","answer":"Stream 1 = 20 kW/°C; Stream 2 = 40 kW/°C","explain":"Stream 2 has a duty of 3,600 kW over 90 °C, so CP = 40."},{"prompt":"Add the CPs of the streams present.","answer":"CP composite = 20 + 40 = 60 kW/°C","explain":"The sum gives the slope of the hot composite curve in that interval."}],"order":2457}
]$cards$::jsonb);
